using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed class CalculatePayableTotal
{
    private const int MaxRatePercent = 10;

    public int For(LoyaltyTier tier, int subtotalCents)
    {
        var ratePercent = Math.Min(BaseRatePercent(tier) + OrderSizeBonusPercent(subtotalCents), MaxRatePercent);
        var discountCents = (int)((long)subtotalCents * ratePercent / 100);

        return subtotalCents - discountCents;
    }

    private static int BaseRatePercent(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 7,
        LoyaltyTier.Gold => 9,
        _ => throw new ArgumentOutOfRangeException(nameof(tier), tier, "Unapproved loyalty tier.")
    };

    private static int OrderSizeBonusPercent(int subtotalCents) => subtotalCents switch
    {
        >= 20000 => 3,
        >= 5000 => 1,
        _ => 0
    };
}
E
